import { z } from "zod";

/** Terminal workflow state for auto-close (POC). */
export const TERMINAL_CASE_STATUS = "resolved" as const;

export const caseStatusSchema = z.enum([
	"open",
	"in_progress",
	"investigating",
	"blocked",
	"on_hold",
	"resolved",
]);

export type CaseStatus = z.infer<typeof caseStatusSchema>;

export const caseClosurePredicateSchema = z.enum([
	"resolution_confirmed",
	"invoice_paid",
	"repair_completed",
]);

export type CaseClosurePredicate = z.infer<typeof caseClosurePredicateSchema>;

export const scopeHintSchema = z.enum(["property", "house", "apartment"]);

export type CaseScopeHint = z.infer<typeof scopeHintSchema>;

/**
 * Normalized case shape after validation (R2.0).
 * `caseKey` is the stable match key; it may be supplied by extractors but
 * the lifecycle service recomputes identity from scope + signals (R2.3).
 */
export const caseIntentSchema = z
	.object({
		title: z.string().min(1),
		summary: z.string(),
		status: caseStatusSchema,
		scopeHint: scopeHintSchema,
		primarySignal: z.string().min(1),
		closurePredicate: caseClosurePredicateSchema.optional(),
		confidence: z.number().min(0).max(1),
	})
	.strict();

export type CaseIntent = z.infer<typeof caseIntentSchema>;

/** Optional extractor hints; `caseKey` must not be trusted for identity (R2.3). */
export const rawCaseIntentSchema = z
	.object({
		caseKey: z.string().optional(),
		title: z.string().min(1),
		summary: z.string(),
		status: caseStatusSchema,
		scopeHint: scopeHintSchema,
		primarySignal: z.string().min(1),
		closurePredicate: caseClosurePredicateSchema.optional(),
		confidence: z.number().min(0).max(1),
	})
	.strict();

export type RawCaseIntent = z.infer<typeof rawCaseIntentSchema>;

export const caseUpsertCommandSchema = z
	.object({
		caseKey: z.string().min(1),
		title: z.string().min(1),
		summary: z.string(),
		status: caseStatusSchema,
		propertyId: z.string().min(1),
		houseId: z.string().optional(),
		apartmentId: z.string().optional(),
		ownerUserId: z.string().min(1),
		closurePredicate: caseClosurePredicateSchema.optional(),
	})
	.refine(
		(cmd) => {
			if (cmd.apartmentId && !cmd.houseId) return false;
			return true;
		},
		{ message: "apartment scope requires houseId" },
	);

export type CaseUpsertCommand = z.infer<typeof caseUpsertCommandSchema>;

export const caseExtractorResponseSchema = z
	.object({
		cases: z.array(rawCaseIntentSchema),
	})
	.strict();

export type CaseExtractorResponse = z.infer<typeof caseExtractorResponseSchema>;

export function parseCaseExtractorResponse(data: unknown): CaseIntent[] {
	const parsed = caseExtractorResponseSchema.safeParse(data);
	if (!parsed.success) {
		return [];
	}
	return parsed.data.cases.map((row) => caseIntentSchema.parse(row));
}

import type { ResolvedHierarchyScope } from "../services/HierarchyResolver";

/**
 * Deterministic case identity (R2.3):
 * `caseKey = normalize(scopeBucket + "|" + primarySignal + "|" + titleFingerprint)`
 *
 * - `scopeBucket`: `p:{propertyId}` | `h:{houseId}` | `a:{apartmentId}`
 * - `primarySignal`: extractor signal (invoice id, ticket ref, etc.), slug-stabilized
 * - `titleFingerprint`: first significant words of title, slug-stabilized
 */
export function scopeBucketFromResolvedScope(scope: ResolvedHierarchyScope): string {
	if (scope.scopeType === "apartment" && scope.apartmentId) {
		return `a:${scope.apartmentId}`;
	}
	if (scope.scopeType === "house" && scope.houseId) {
		return `h:${scope.houseId}`;
	}
	return `p:${scope.propertyId}`;
}

export function normalizeCaseKeyPart(value: string): string {
	return value
		.trim()
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-+|-+$/g, "");
}

export function titleFingerprint(title: string): string {
	const normalized = normalizeCaseKeyPart(title);
	return normalized.slice(0, 48) || "untitled";
}

export function computeCaseKey(
	scope: ResolvedHierarchyScope,
	primarySignal: string,
	title: string,
): string {
	const bucket = scopeBucketFromResolvedScope(scope);
	const sig = normalizeCaseKeyPart(primarySignal);
	const fp = titleFingerprint(title);
	return normalizeCaseKeyPart(`${bucket}|${sig}|${fp}`);
}

import type { CaseIntent } from "./caseDomain";
import type { ResolvedHierarchyScope } from "../services/HierarchyResolver";
import { computeCaseKey } from "./caseIdentity";

export type ScopedCaseIntent = {
	intent: CaseIntent;
	scope: ResolvedHierarchyScope;
	caseKey: string;
};

/**
 * Groups intents by computed `caseKey` and merges collisions (R2.8).
 * Higher `confidence` wins title and status; other titles become summary bullets.
 */
export function groupIntentsByCaseKey(rows: ScopedCaseIntent[]): Map<string, ScopedCaseIntent[]> {
	const map = new Map<string, ScopedCaseIntent[]>();
	for (const row of rows) {
		const list = map.get(row.caseKey) ?? [];
		list.push(row);
		map.set(row.caseKey, list);
	}
	return map;
}

export function mergeCaseIntentsForSameKey(group: ScopedCaseIntent[]): CaseIntent {
	if (group.length === 0) {
		throw new Error("mergeCaseIntentsForSameKey requires at least one intent");
	}
	const sorted = [...group].sort((a, b) => b.intent.confidence - a.intent.confidence);
	const winner = sorted[0].intent;
	const summaryParts: string[] = [winner.summary.trim()].filter(Boolean);

	for (const row of sorted.slice(1)) {
		const other = row.intent;
		if (normalizeTitle(other.title) !== normalizeTitle(winner.title)) {
			summaryParts.push(`• (alt title) ${other.title}: ${other.summary.trim()}`.trim());
		} else if (other.summary.trim() && other.summary.trim() !== winner.summary.trim()) {
			summaryParts.push(`• ${other.summary.trim()}`);
		}
	}

	const closurePredicate =
		sorted.find((row) => row.intent.closurePredicate)?.intent.closurePredicate ??
		winner.closurePredicate;

	return {
		title: winner.title,
		summary: summaryParts.join(" "),
		status: winner.status,
		scopeHint: winner.scopeHint,
		primarySignal: winner.primarySignal,
		closurePredicate,
		confidence: winner.confidence,
	};
}

function normalizeTitle(title: string): string {
	return title.trim().toLowerCase().replace(/\s+/g, " ");
}

export function attachCaseKeys(
	intents: CaseIntent[],
	resolveScope: (intent: CaseIntent) => ResolvedHierarchyScope,
): ScopedCaseIntent[] {
	return intents.map((intent) => {
		const scope = resolveScope(intent);
		const caseKey = computeCaseKey(scope, intent.primarySignal, intent.title);
		return { intent, scope, caseKey };
	});
}

/**
 * Best-effort scope signals from raw document text (eml/pdf fixture text).
 * Mirrors `deriveDocumentMetadataFromFact` heuristics for case extraction.
 */
export function deriveDocumentMetadataFromText(raw: string): {
	houseId?: string;
	apartmentId?: string;
	unitLabel?: string;
} {
	const apartmentMatch = raw.match(/\b([A-Z]{3}-\d{3}-H\d+-A\d+)\b/);
	if (apartmentMatch?.[1]) {
		const apartmentId = apartmentMatch[1];
		const houseId = apartmentId.split("-A")[0];
		return { houseId, apartmentId };
	}

	const houseMatch = raw.match(/\b([A-Z]{3}-\d{3}-H\d+)\b/);
	if (houseMatch?.[1]) {
		return { houseId: houseMatch[1] };
	}

	const unitLabelMatch = raw.match(/\b(Unit\s+\d+)\b/i);
	if (unitLabelMatch?.[1]) {
		return { unitLabel: unitLabelMatch[1] };
	}

	return {};
}

import type { CaseIntent } from "../case/caseDomain";
import { parseCaseExtractorResponse } from "../case/caseDomain";
import type { LlmJsonClient } from "../types";

export interface CaseExtractionContext {
	propertyId: string;
}

export interface CaseExtractor {
	extract(documentText: string, context: CaseExtractionContext): Promise<CaseIntent[]>;
}

interface CaseExtractorOptions {
	strictErrors?: boolean;
}

export class GeminiCaseExtractor implements CaseExtractor {
	constructor(
		private readonly llmClient: LlmJsonClient,
		private readonly options: CaseExtractorOptions = {},
	) {}

	async extract(
		documentText: string,
		_context: CaseExtractionContext,
	): Promise<CaseIntent[]> {
		const prompt = `
You are a case tracker for property management. Extract 0..N operational cases from the document.
Return valid JSON only using this shape:
{
  "cases": [
    {
      "title": "short human title",
      "summary": "1-3 sentences",
      "status": "open" | "in_progress" | "investigating" | "blocked" | "on_hold" | "resolved",
      "scopeHint": "property" | "house" | "apartment",
      "primarySignal": "stable token such as invoice id, ticket id, or normalized subject stem",
      "closurePredicate": "resolution_confirmed" | "invoice_paid" | "repair_completed" | null,
      "confidence": 0.0
    }
  ]
}

Rules:
- If there is no actionable workflow, return {"cases":[]}.
- primarySignal must be stable across related emails about the same issue.
- closurePredicate only when the text clearly implies how the case could auto-close.

Document:
"""${documentText}"""
`;

		try {
			const response = await this.llmClient.generateJson<unknown>(prompt);
			return parseCaseExtractorResponse(response);
		} catch (error) {
			if (this.options.strictErrors) {
				throw new Error(
					`CaseExtractor failed: ${
						error instanceof Error ? error.message : "unknown error"
					}`,
				);
			}
			return [];
		}
	}
}

import { and, eq, inArray, or } from "drizzle-orm";

import { cases, factApartments, factCases, factHouses, facts } from "../../db/schema";
import type {
	CaseClosurePredicate,
	CaseStatus,
	CaseUpsertCommand,
} from "../case/caseDomain";
import { TERMINAL_CASE_STATUS } from "../case/caseDomain";
import type { CaseIntent } from "../case/caseDomain";
import { computeCaseKey } from "../case/caseIdentity";
import {
	attachCaseKeys,
	groupIntentsByCaseKey,
	mergeCaseIntentsForSameKey,
	type ScopedCaseIntent,
} from "../case/caseIntentMerge";
import type { HierarchyResolver } from "./HierarchyResolver";
import type { ResolvedHierarchyScope } from "./HierarchyResolver";
import { createHash } from "node:crypto";
import type { BaselineDryRunDb } from "../pipelines/caseTypes";

const ACTIVE_STATUSES: CaseStatus[] = [
	"open",
	"in_progress",
	"investigating",
];

export type NewFactSnapshot = {
	id: string;
	propertyId: string;
	key: string;
	value: string;
	scope: ResolvedHierarchyScope;
};

export interface CaseLifecycleCounters {
	casesOpened: number;
	casesUpdated: number;
	casesResolved: number;
}

function deterministicCaseId(propertyId: string, caseKey: string): string {
	const h = createHash("sha256").update(`${propertyId}::${caseKey}`).digest("hex");
	return `case-${h.slice(0, 26)}`;
}

export function factValueImpliesClosure(value: string): boolean {
	const v = value.trim().toLowerCase();
	return (
		v === "true" ||
		v === "yes" ||
		v === "paid" ||
		v === "1" ||
		v === "completed" ||
		v === "resolved" ||
		v === "confirmed"
	);
}

export function factSatisfiesClosurePredicate(
	factKey: string,
	factValue: string,
	predicate: CaseClosurePredicate,
): boolean {
	return factKey === predicate && factValueImpliesClosure(factValue);
}

function scopesAlign(caseRow: CaseUpsertCommand, factScope: ResolvedHierarchyScope): boolean {
	if (caseRow.apartmentId) {
		return (
			factScope.scopeType === "apartment" && factScope.apartmentId === caseRow.apartmentId
		);
	}
	if (caseRow.houseId) {
		return (
			(factScope.scopeType === "house" && factScope.houseId === caseRow.houseId) ||
			(factScope.scopeType === "apartment" && factScope.houseId === caseRow.houseId)
		);
	}
	return factScope.propertyId === caseRow.propertyId;
}

export class CaseLifecycleService {
	constructor(
		private readonly db: BaselineDryRunDb,
		private readonly options: { defaultOwnerUserId?: string } = {},
	) {}

	defaultOwner(): string {
		return this.options.defaultOwnerUserId ?? "user-1";
	}

	resolveScopeForIntent(
		resolver: Pick<HierarchyResolver, "resolve">,
		propertyId: string,
		documentMetadata: {
			houseId?: string;
			apartmentId?: string;
			unitLabel?: string;
		},
		intent: CaseIntent,
	): Promise<ResolvedHierarchyScope> {
		return resolver.resolve({
			propertyId,
			documentMetadata,
			extractedFact: {
				key: intent.primarySignal,
				value: intent.title,
			},
		});
	}

	mergeAndNormalizeIntents(rows: ScopedCaseIntent[]): Map<string, { merged: CaseIntent; scope: ResolvedHierarchyScope; caseKey: string }> {
		const groups = groupIntentsByCaseKey(rows);
		const out = new Map<string, { merged: CaseIntent; scope: ResolvedHierarchyScope; caseKey: string }>();
		for (const [caseKey, group] of groups) {
			const merged = mergeCaseIntentsForSameKey(group);
			const scope = group[0].scope;
			const recomputedKey = computeCaseKey(scope, merged.primarySignal, merged.title);
			const key = recomputedKey === caseKey ? caseKey : recomputedKey;
			out.set(key, { merged, scope, caseKey: key });
		}
		return out;
	}

	async upsertCaseFromCommand(
		cmd: CaseUpsertCommand,
		nowIso: string,
	): Promise<{ opened: boolean; updated: boolean }> {
		const id = deterministicCaseId(cmd.propertyId, cmd.caseKey);
		const existing = await this.db.query.cases.findFirst({
			where: (c, { and: a, eq: e }) => a(e(c.propertyId, cmd.propertyId), e(c.caseKey, cmd.caseKey)),
		});

		if (!existing) {
			await this.db.insert(cases).values({
				id,
				propertyId: cmd.propertyId,
				houseId: cmd.houseId ?? null,
				apartmentId: cmd.apartmentId ?? null,
				ownerUserId: cmd.ownerUserId,
				caseKey: cmd.caseKey,
				closurePredicate: cmd.closurePredicate ?? null,
				title: cmd.title,
				summary: cmd.summary,
				status: cmd.status,
				createdAt: nowIso,
				updatedAt: nowIso,
			});
			return { opened: true, updated: false };
		}

		const nextStatus =
			existing.status === TERMINAL_CASE_STATUS ? existing.status : cmd.status;
		await this.db
			.update(cases)
			.set({
				title: cmd.title,
				summary: cmd.summary,
				status: nextStatus,
				closurePredicate: cmd.closurePredicate ?? existing.closurePredicate,
				updatedAt: nowIso,
				houseId: cmd.houseId ?? existing.houseId,
				apartmentId: cmd.apartmentId ?? existing.apartmentId,
			})
			.where(eq(cases.id, existing.id));

		return { opened: false, updated: true };
	}

	async processIntentsForDocument(input: {
		propertyId: string;
		intents: CaseIntent[];
		resolver: Pick<HierarchyResolver, "resolve">;
		documentMetadata: {
			houseId?: string;
			apartmentId?: string;
			unitLabel?: string;
		};
		nowIso: string;
	}): Promise<CaseLifecycleCounters> {
		const counters: CaseLifecycleCounters = {
			casesOpened: 0,
			casesUpdated: 0,
			casesResolved: 0,
		};
		if (input.intents.length === 0) {
			return counters;
		}

		const scoped: ScopedCaseIntent[] = [];
		for (const intent of input.intents) {
			const scope = await this.resolveScopeForIntent(
				input.resolver,
				input.propertyId,
				input.documentMetadata,
				intent,
			);
			const caseKey = computeCaseKey(scope, intent.primarySignal, intent.title);
			scoped.push({ intent, scope, caseKey });
		}

		const mergedMap = this.mergeAndNormalizeIntents(scoped);
		const owner = this.defaultOwner();

		for (const { merged, scope, caseKey } of mergedMap.values()) {
			const cmd: CaseUpsertCommand = {
				caseKey,
				title: merged.title,
				summary: merged.summary,
				status: merged.status,
				propertyId: input.propertyId,
				houseId: scope.houseId,
				apartmentId: scope.apartmentId,
				ownerUserId: owner,
				closurePredicate: merged.closurePredicate,
			};
			const { opened, updated } = await this.upsertCaseFromCommand(cmd, input.nowIso);
			if (opened) counters.casesOpened += 1;
			if (updated) counters.casesUpdated += 1;
		}

		return counters;
	}

	async linkFactsToCasesHeuristic(input: {
		caseKeys: string[];
		propertyId: string;
		factsForBatch: Array<{ id: string; key: string; value: string }>;
	}): Promise<number> {
		if (input.caseKeys.length === 0 || input.factsForBatch.length === 0) {
			return 0;
		}
		const caseRows = await this.db.query.cases.findMany({
			where: (c, { and: a, eq: e, inArray: inArr }) =>
				a(e(c.propertyId, input.propertyId), inArr(c.caseKey, input.caseKeys)),
		});
		let links = 0;
		for (const caseRow of caseRows) {
			const signal = caseRow.caseKey.split("|")[1] ?? "";
			const normSignal = signal.replace(/[^a-z0-9]+/gi, "").toLowerCase();
			for (const fact of input.factsForBatch) {
				const fk = fact.key.toLowerCase();
				const fv = String(fact.value).toLowerCase();
				const overlap =
					normSignal.length >= 4 &&
					(fk.includes(normSignal) ||
						fv.includes(normSignal) ||
						normSignal.includes(fk.replace(/[^a-z0-9]/g, "")));
				if (!overlap) continue;
				try {
					await this.db.insert(factCases).values({
						factId: fact.id,
						caseId: caseRow.id,
					});
					links += 1;
				} catch {
					/* duplicate PK */
				}
			}
		}
		return links;
	}

	async evaluateAutoClose(input: {
		propertyId: string;
		newFacts: NewFactSnapshot[];
		nowIso: string;
	}): Promise<number> {
		if (input.newFacts.length === 0) {
			return 0;
		}
		let resolved = 0;
		const openCases = await this.db.query.cases.findMany({
			where: (c, { and: a, eq: e, isNotNull, inArray: inArr, or: o }) =>
				a(
					e(c.propertyId, input.propertyId),
					isNotNull(c.closurePredicate),
					inArr(c.status, ACTIVE_STATUSES),
				),
		});

		for (const caseRow of openCases) {
			const pred = caseRow.closurePredicate as CaseClosurePredicate | null;
			if (!pred) continue;

			for (const fact of input.newFacts) {
				if (!factSatisfiesClosurePredicate(fact.key, fact.value, pred)) {
					continue;
				}
				const cmdScope: ResolvedHierarchyScope =
					caseRow.apartmentId && caseRow.houseId
						? {
								scopeType: "apartment",
								propertyId: caseRow.propertyId,
								houseId: caseRow.houseId,
								apartmentId: caseRow.apartmentId,
							}
						: caseRow.houseId
							? {
									scopeType: "house",
									propertyId: caseRow.propertyId,
									houseId: caseRow.houseId,
								}
							: { scopeType: "property", propertyId: caseRow.propertyId };

				if (!scopesAlign(
					{
						caseKey: caseRow.caseKey,
						title: caseRow.title,
						summary: caseRow.summary,
						status: caseRow.status as CaseStatus,
						propertyId: caseRow.propertyId,
						houseId: caseRow.houseId ?? undefined,
						apartmentId: caseRow.apartmentId ?? undefined,
						ownerUserId: caseRow.ownerUserId,
						closurePredicate: pred,
					},
					fact.scope,
				)) {
					continue;
				}
				void cmdScope;
				await this.db
					.update(cases)
					.set({ status: TERMINAL_CASE_STATUS, updatedAt: input.nowIso })
					.where(eq(cases.id, caseRow.id));
				resolved += 1;
				break;
			}
		}
		return resolved;
	}
}

/** Builds fact scope snapshots using link tables (post-insert). */
export async function loadFactScopes(
	db: BaselineDryRunDb,
	factIds: string[],
): Promise<Map<string, ResolvedHierarchyScope>> {
	const map = new Map<string, ResolvedHierarchyScope>();
	if (factIds.length === 0) return map;

	const factRows = await db.query.facts.findMany({
		where: (f, { inArray: inArr }) => inArr(f.id, factIds),
		with: {
			houseLinks: true,
			apartmentLinks: true,
		},
	});

	for (const row of factRows) {
		const apartmentId = row.apartmentLinks[0]?.apartmentId;
		const houseId = row.houseLinks[0]?.houseId;
		const scope: ResolvedHierarchyScope = apartmentId
			? {
					scopeType: "apartment",
					propertyId: row.propertyId,
					houseId: houseId ?? row.propertyId,
					apartmentId,
				}
			: houseId
				? { scopeType: "house", propertyId: row.propertyId, houseId }
				: { scopeType: "property", propertyId: row.propertyId };
		map.set(row.id, scope);
	}
	return map;
}

