import { describe, expect, it } from "vitest";
import {
	caseIntentSchema,
	parseCaseExtractorResponse,
	rawCaseIntentSchema,
} from "../caseDomain";

describe("caseDomain (R2.0)", () => {
	it("rejects malformed raw intents", () => {
		expect(rawCaseIntentSchema.safeParse({ title: "" }).success).toBe(false);
		expect(
			rawCaseIntentSchema.safeParse({
				title: "Ok",
				summary: "s",
				status: "bogus",
				scopeHint: "property",
				primarySignal: "sig",
				confidence: 0.5,
			}).success,
		).toBe(false);
	});

	it("accepts valid intents", () => {
		const row = {
			title: "Invoice dispute",
			summary: "Tenant challenges heating bill.",
			status: "open" as const,
			scopeHint: "apartment" as const,
			primarySignal: "INV-1001",
			closurePredicate: "invoice_paid" as const,
			confidence: 0.88,
		};
		expect(() => caseIntentSchema.parse(row)).not.toThrow();
	});

	it("parses strict extractor JSON into intents", () => {
		const intents = parseCaseExtractorResponse({
			cases: [
				{
					title: "Leak",
					summary: "Bathroom leak",
					status: "open",
					scopeHint: "house",
					primarySignal: "TICKET-7",
					confidence: 0.9,
				},
			],
		});
		expect(intents).toHaveLength(1);
		expect(intents[0].primarySignal).toBe("TICKET-7");
	});

	it("returns empty list when envelope is invalid", () => {
		expect(parseCaseExtractorResponse({ cases: "nope" })).toEqual([]);
		expect(parseCaseExtractorResponse(null)).toEqual([]);
	});
});

import { describe, expect, it } from "vitest";
import {
	computeCaseKey,
	normalizeCaseKeyPart,
	scopeBucketFromResolvedScope,
	titleFingerprint,
} from "../caseIdentity";

/**
 * Documented identity formula (R2.3):
 * caseKey = normalize(scopeBucket + "|" + primarySignal + "|" + titleFingerprint)
 * - scopeBucket: p:{propertyId} | h:{houseId} | a:{apartmentId}
 * - primarySignal + titleFingerprint: slug-normalized (lowercase, non-alnum → '-')
 */
describe("caseIdentity (R2.3)", () => {
	it("builds stable keys for apartment scope", () => {
		const scope = {
			scopeType: "apartment" as const,
			propertyId: "LIE-001",
			houseId: "LIE-001-H1",
			apartmentId: "LIE-001-H1-A1",
		};
		expect(scopeBucketFromResolvedScope(scope)).toBe("a:LIE-001-H1-A1");
		expect(
			computeCaseKey(scope, "INV-2044", "Heating invoice dispute Q1"),
		).toBe(
			normalizeCaseKeyPart(
				`a:LIE-001-H1-A1|${normalizeCaseKeyPart("INV-2044")}|${titleFingerprint("Heating invoice dispute Q1")}`,
			),
		);
	});

	it("matches across phrasing when primary signal and title fingerprint align", () => {
		const scope = {
			scopeType: "property" as const,
			propertyId: "LIE-001",
		};
		const k1 = computeCaseKey(scope, "roof-damage-2026", "Roof damage after storm");
		const k2 = computeCaseKey(scope, "roof-damage-2026", "Roof Damage — After Storm");
		expect(k1).toBe(k2);
	});
});

import { describe, expect, it } from "vitest";
import type { CaseIntent } from "../caseDomain";
import { mergeCaseIntentsForSameKey, type ScopedCaseIntent } from "../caseIntentMerge";

describe("caseIntentMerge (R2.8)", () => {
	const scope = {
		scopeType: "house" as const,
		propertyId: "LIE-001",
		houseId: "LIE-001-H1",
	};

	function scoped(intent: CaseIntent, caseKey: string): ScopedCaseIntent {
		return { intent, scope, caseKey };
	}

	it("prefers higher confidence title and appends alt-title bullet to summary", () => {
		const a: CaseIntent = {
			title: "Short title",
			summary: "First summary",
			status: "open",
			scopeHint: "house",
			primarySignal: "SIG-1",
			confidence: 0.55,
		};
		const b: CaseIntent = {
			title: "Longer authoritative title",
			summary: "Second summary",
			status: "in_progress",
			scopeHint: "house",
			primarySignal: "SIG-1",
			closurePredicate: "repair_completed",
			confidence: 0.95,
		};
		const merged = mergeCaseIntentsForSameKey([
			scoped(a, "k1"),
			scoped(b, "k1"),
		]);
		expect(merged.title).toBe("Longer authoritative title");
		expect(merged.status).toBe("in_progress");
		expect(merged.closurePredicate).toBe("repair_completed");
		expect(merged.summary).toContain("• (alt title) Short title:");
	});

	it("keeps single intent unchanged", () => {
		const intent: CaseIntent = {
			title: "Only",
			summary: "S",
			status: "open",
			scopeHint: "property",
			primarySignal: "p1",
			confidence: 0.8,
		};
		expect(mergeCaseIntentsForSameKey([scoped(intent, "k")])).toEqual(intent);
	});
});

